python3 - <<'EOF'
from quantum_circuit.openqasm import parse
from quantum_circuit.optimizer import optimize
prog = parse('OPENQASM 2.0;
include "qelib1.inc";
qreg q[2];
creg c[2];
s q[0];
h q[1];
sdg q[0];
t q[1];
x q[0];
tdg q[1];
')
gates, changed, qasm = optimize(prog)
assert [g.kind for g in gates] == ["x", "h"], gates  # canonical order sorts by min qubit
prog = parse('OPENQASM 2.0;
include "qelib1.inc";
qreg q[2];
creg c[2];
swap q[1],q[0];
')
gates, changed, qasm = optimize(prog)
assert "swap q[0],q[1];" in qasm
print("optimize rules OK")
EOF
